// proves: a call through a fn value the body itself minted calls that code, and only that one. A
// lambda handed to a list method, capturing or not, is called directly; a closure rebound, held in
// a record or a list, handed to another fn's seat, chosen by a branch or rebound in a loop is
// called as the fn it holds when the call is made, never as one it held before.
type Held = { f: fn(int) -> int }

fn through(g: fn(int) -> int, v: int) -> int { g(v) }

fn picked(c: bool) -> fn(int) -> int { if c { (x: int) -> x + 1 } else { (x: int) -> x * 2 } }

let found = [3, 8, 12].find(it > 5) ?? 0
mut f = (x: int) -> x + 100
f = (x: int) -> x - 100
let rebound = f(1)
let held = Held { f: (x: int) -> x * 10 }
let in_record = (held.f)(4)
let fs = [(x: int) -> x + 1, (x: int) -> x + 2]
let in_list = fs[1](5)
let handed = through((x: int) -> x * x, 7)
let branch = picked(false)(6)
mut acc = 0
for k in 0..3 {
    let g = if k == 1 { (x: int) -> x * 100 } else { (x: int) -> x + k }
    acc = acc + g(1)
}
let n = 5
let captured = [1, 2, 3].map(it + n).sum()
"${found} ${rebound} ${in_record} ${in_list} ${handed} ${branch} ${acc} ${captured}"
EOF
