#include <stdint.h>
#include <stdio.h>
#include <time.h>
void* avra_cell_unique(void* slot);
void avra_array_push(void* arr, int64_t v);
void* avra_array_sized(int64_t n);
void* avra_array_new(void);
void avra_rc_release(void* p);
void* avra_array_empty_words(void);
extern void* avra_array_empty(void) __attribute__((weak));
static double now(void) { struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t); return t.tv_sec + t.tv_nsec * 1e-9; }
int main(int argc, char** argv) {
    (void)argv;
    long n = 37000000L * (argc > 5 ? 2 : 1);
    void* empty = avra_array_new();          /* a stand-in made below for the static */
    avra_rc_release(empty);
    volatile int64_t sink = 0;
    for (int round = 0; round < 3; round++) {
        double t0 = now();
        for (long i = 0; i < n; i++) {        /* open of the immortal empty, then the push */
            void* slot = avra_array_empty_words();
            void* c = avra_cell_unique(&slot);
            avra_array_push(c, i);
            sink += *(int64_t*)c;
            avra_rc_release(c);
        }
        double t1 = now();
        for (long i = 0; i < n; i++) {        /* one fresh list sized for the push */
            void* c = avra_array_sized(8);
            avra_array_push(c, i);
            sink += *(int64_t*)c;
            avra_rc_release(c);
        }
        double t2 = now();
        for (long i = 0; i < n; i++) {        /* a fresh empty grown by its push */
            void* c = avra_array_new();
            avra_array_push(c, i);
            sink += *(int64_t*)c;
            avra_rc_release(c);
        }
        double t3 = now();
        printf("open %.1f ns  sized(8) %.1f ns  new+grow %.1f ns  (n=%ld)\n", (t1-t0)/n*1e9, (t2-t1)/n*1e9, (t3-t2)/n*1e9, n);
    }
    return (int)(sink & 1);
}
EOF
