/// A technique of docs/ZERO_COST.md a census site's shape names.
enum Technique {
    StackRecords
    StridedList
    NullableFlatRecord
    StaticMethodTables
    InternedNames
    ReuseInPlace
    MoveAtLastUse
}

/// Every technique, in the registry's order.
const TECHNIQUES: List<Technique> = [
    Technique.StackRecords,
    Technique.StridedList,
    Technique.NullableFlatRecord,
    Technique.StaticMethodTables,
    Technique.InternedNames,
    Technique.ReuseInPlace,
    Technique.MoveAtLastUse,
]

/// The technique as a candidate line names it.
fn technique_word(t: Technique) -> string {
    match t {
        .StackRecords -> "stack-records",
        .StridedList -> "strided-list",
        .NullableFlatRecord -> "nullable-flat-record",
        .StaticMethodTables -> "static-method-tables",
        .InternedNames -> "interned-names",
        .ReuseInPlace -> "reuse-in-place",
        .MoveAtLastUse -> "move-at-last-use",
    }
}

/// One site a technique would make cheaper: the Avra fn it stands in, and how often it paid.
type Candidate = { technique: Technique, symbol: string, count: int }

/// How many sites of each technique are named.
const TOP: int = 10

/// Every candidate a report's site lines show.
fn candidates_in(report: string) -> List<Candidate> { flatten([candidates_of(line.split(" ")) for line in report.split("\n")]) }

/// The candidates one site line shows, read by its words:
///   pair|move: <made or retained at> <dropped or released at> <count> <bytes>
///   reuse: <freed at> <made at> <count> <bytes>
///   typed|streq: site <at> <count> <bytes>B <label…>
fn candidates_of(words: List<string>) -> List<Candidate> {
    if words.length < 4 { return [] }
    let kind = words[0]
    if kind == "pair:" || kind == "move:" {
        if words[1] != words[2] || !avra_symbol(words[1]) { return [] }
        let t = if kind == "pair:" { Technique.StackRecords } else { Technique.MoveAtLastUse }
        return counted(t, words[1], words[3])
    }
    if kind == "reuse:" { return if avra_symbol(words[2]) { counted(Technique.ReuseInPlace, words[2], words[3]) } else { [] } }
    if words[1] != "site" || !avra_symbol(words[2]) { return [] }
    if kind == "streq:" { return counted(Technique.InternedNames, words[2], words[3]) }
    if kind != "typed:" { return [] }
    let label = words.drop(5).join(" ")
    let t? = labelled(label) else { return [] }
    counted(t, words[2], words[3])
}

/// The technique a box's census label names: a record of scalars pushed into a list, a slot box, a
/// `dyn` box; absent for any other.
fn labelled(label: string) -> Technique? {
    when {
        label.contains("flat-pushed") -> Technique.StridedList
        label.starts_with("box slot") -> Technique.NullableFlatRecord
        label.starts_with("box dyn") -> Technique.StaticMethodTables
        _ -> null
    }
}

/// The candidate of `t` at `symbol`, paid `count` times; none where the count is no number.
fn counted(t: Technique, symbol: string, count: string) -> List<Candidate> {
    let n? = parse_int(count) else { return [] }
    [Candidate { technique: t, symbol: symbol, count: n }]
}

